# Version 30 card drawings: people, actions, feelings, places, time, positions and qualities for the core course.
# Same style as draw.py (ink outline, flat colour, 160x160). Run through draw.py: it exec()s this file before saving.
# A word that means several things (phải, nên, hay, về, chỉ, ký ...) gets no picture, because pictures are keyed by the Vietnamese word.

HAIR = DK
BLUE = "#3E5F7A"; NAVY = "#31506A"; GREY = "#8A8A84"; SKY2 = "#9FC6D9"; BRICK = "#C96A45"

def limb(pts, col, w=7):
    d = "M" + " L".join("%g %g" % p for p in pts)
    return L(d, w + 3.4, INK) + L(d, w, col)

def fig(x=80, base=142, s=1.0, shirt=TE, pants=BLUE, hair="short", hc=DK, face="smile", skin=SK,
        la=None, ra=None, ll=None, rl=None, skirt=None, back="", front="", head_dy=0, flip=False):
    """A standing person, feet at y=0, head centre at (0,-92). Limbs are point lists in that frame."""
    la = la or [(-12, -68), (-18, -50), (-19, -34)]
    ra = ra or [(12, -68), (18, -50), (19, -34)]
    ll = ll or [(-6, -36), (-7, -18), (-8, 0)]
    rl = rl or [(6, -36), (7, -18), (8, 0)]
    hy = -92 + head_dy
    o = back
    if hair == "long": o += P(f"M-16 {hy} Q-18 {hy-20} 0 {hy-19} Q18 {hy-20} 16 {hy} L18 {hy+26} L-18 {hy+26} Z", hc)
    o += limb(ll, pants) + limb(rl, pants)
    o += E(ll[-1][0] - 2, 1, 6, 3.4, DK) + E(rl[-1][0] + 2, 1, 6, 3.4, DK)
    if skirt: o += P("M-14 -40 L-20 -14 H20 L14 -40 Z", skirt)
    o += R(-13, -74, 26, 40, shirt, 7)
    o += limb(la, shirt, 6.4) + limb(ra, shirt, 6.4)
    o += C(la[-1][0], la[-1][1], 3.6, skin) + C(ra[-1][0], ra[-1][1], 3.6, skin)
    o += R(-4, hy + 12, 8, 6, skin, 2)
    o += C(0, hy, 14, skin)
    if hair == "short": o += P(f"M-14 {hy-2} Q-14 {hy-16} 0 {hy-16} Q14 {hy-16} 14 {hy-2} Q9 {hy-9} 0 {hy-8} Q-9 {hy-9} -14 {hy-2} Z", hc)
    elif hair == "long": o += P(f"M-14 {hy-2} Q-12 {hy-16} 0 {hy-16} Q12 {hy-16} 14 {hy-2} Q4 {hy-10} -6 {hy-6} Q-10 {hy-5} -14 {hy-2} Z", hc)
    elif hair == "bun": o += C(0, hy - 17, 6, hc) + P(f"M-14 {hy-2} Q-14 {hy-16} 0 {hy-16} Q14 {hy-16} 14 {hy-2} Q9 {hy-9} 0 {hy-8} Q-9 {hy-9} -14 {hy-2} Z", hc)
    elif hair == "bald": o += P(f"M-14 {hy-1} Q-15 {hy-8} -11 {hy-10} L-9 {hy-4} Z M14 {hy-1} Q15 {hy-8} 11 {hy-10} L9 {hy-4} Z", hc)
    ey = hy - 1
    if face == "sleep": o += L(f"M-7 {ey} q2 2 4 0 M3 {ey} q2 2 4 0", 1.8)
    elif face == "wide": o += C(-5, ey, 2.6, WH) + C(5, ey, 2.6, WH) + D(-5, ey, 1.3) + D(5, ey, 1.3)
    else: o += D(-5, ey, 1.8) + D(5, ey, 1.8)
    my = hy + 7
    if face in ("smile", "sleep"): o += L(f"M-5 {my-1} q5 4 10 0", 1.8)
    elif face == "big": o += P(f"M-6 {my-2} q6 7 12 0 Z", "#8E2F1E")
    elif face == "sad": o += L(f"M-5 {my+2} q5 -4 10 0", 1.8) + L(f"M-8 {ey-5} l5 -2 M8 {ey-5} l-5 -2", 1.6)
    elif face == "angry": o += L(f"M-5 {my+2} q5 -4 10 0", 1.8) + L(f"M-8 {ey-6} l5 2.5 M8 {ey-6} l-5 2.5", 2)
    elif face in ("open", "wide"): o += E(0, my, 3, 2.6, "#8E2F1E")
    else: o += L(f"M-4 {my} h8", 1.8)
    o += front
    t = f'translate({x} {base}) scale({-s if flip else s} {s})'
    return f'<g transform="{t}">' + o + '</g>'

def Q(x, y, s=1.0, col=RD):
    """A question mark."""
    return f'<g transform="translate({x} {y}) scale({s})">' + L("M-8 -12 Q-8 -24 0 -24 Q9 -24 9 -15 Q9 -8 0 -5 V2", 5.5, INK) + L("M-8 -12 Q-8 -24 0 -24 Q9 -24 9 -15 Q9 -8 0 -5 V2", 3.2, col) + C(0, 11, 3.4, col) + '</g>'

def bubble(x, y, w=44, h=28, f=WH, dots=True):
    o = P(f"M{x} {y} h{w} q6 0 6 6 v{h-12} q0 6 -6 6 h-{w-14} l-10 9 l2 -9 h-6 q-6 0 -6 -6 v-{h-12} q0 -6 6 -6 Z", f)
    if dots: o += D(x + w/2 - 9, y + h/2, 2.6) + D(x + w/2, y + h/2, 2.6) + D(x + w/2 + 9, y + h/2, 2.6)
    return o

def heart(x, y, s=1.0, col=RD):
    return f'<g transform="translate({x} {y}) scale({s})">' + P("M0 8 C-14 -2 -12 -14 -4 -14 C0 -14 0 -10 0 -9 C0 -10 0 -14 4 -14 C12 -14 14 -2 0 8 Z", col) + '</g>'

def arrow(d, col=RD, w=4):
    return L(d, w + 3, INK) + L(d, w, col)

def head(d, col=RD):
    return P(d, col)

def note(x, y, s=1.0, col=GR):
    return f'<g transform="translate({x} {y}) scale({s})">' + L("M0 0 V-20 L12 -24 V-6", 2.6) + E(-3, 0, 5, 3.6, col) + E(9, -6, 5, 3.6, col) + '</g>'

def cal(mark=None, arr=None):
    o = SH(46, 142) + R(30, 34, 100, 102, WH, 6) + R(30, 34, 100, 26, RD, 6) + R(30, 50, 100, 10, RD, 0) + L("M52 26 v16 M108 26 v16", 5)
    for r in range(4):
        for c in range(5):
            o += R(38 + c * 18, 68 + r * 16, 12, 10, ST if (r, c) != mark else YE, 2)
    if arr: o += arr
    return o


def days(hi, n=3, back=False, fwd=False):
    """43: a strip of days with today marked by a pin. hi = the day this word means (0 = first box). Clearer than a calendar for hôm qua / hôm nay / mai."""
    w = 120 // n; x0 = 80 - (w * n) // 2; o = SH(56, 138) + L("M14 112 H146", 3, ST)
    for i in range(n):
        x = x0 + i * w + 4; f = YE if i == hi else CR
        o += R(x, 62, w - 8, 44, f, 5) + R(x, 62, w - 8, 10, RD if i == hi else ST, 4)
    mid = x0 + (n // 2) * w + w // 2
    o += P(f"M{mid} 40 q-9 0 -9 -9 q0 -9 9 -9 q9 0 9 9 q0 9 -9 9 Z M{mid} 40 L{mid} 58", RD) + D(mid, 31, 3.4, CR)
    hx = x0 + hi * w + w // 2
    if back: o += arrow(f"M{mid-12} 128 H{hx+6} M{hx+14} 120 L{hx+4} 128 L{hx+14} 136", RD, 3)
    if fwd: o += arrow(f"M{mid+12} 128 H{hx-6} M{hx-14} 120 L{hx-4} 128 L{hx-14} 136", RD, 3)
    return o

def clockface(hh, mm, f=CR, x=80, y=84, r=46):
    import math
    o = C(x, y, r, f) + "".join(D(x + (r - 8) * math.sin(k * math.pi / 6), y - (r - 8) * math.cos(k * math.pi / 6), 2.2) for k in range(12))
    ah = (hh % 12 + mm / 60) * math.pi / 6; am = mm * math.pi / 30
    o += L(f"M{x} {y} L{x + r*.5*math.sin(ah):.1f} {y - r*.5*math.cos(ah):.1f}", 4) + L(f"M{x} {y} L{x + r*.75*math.sin(am):.1f} {y - r*.75*math.cos(am):.1f}", 3) + D(x, y, 3.4)
    return o

def box(x, y, w=56, h=44, f=WD):
    return P(f"M{x} {y+10} L{x+12} {y} H{x+w+12} L{x+w} {y+10} Z", "#D9A45B") + R(x, y + 10, w, h, f, 2) + P(f"M{x+w} {y+10} L{x+w+12} {y} V{y+h} L{x+w} {y+h+10} Z", "#A8743C")

def ball(x, y, r=11, col=RD):
    return C(x, y, r, col) + L(f"M{x-r+3} {y-3} q{r-3} -6 {2*r-6} 0", 2, CR)

